        refe = {e['siret']: e for e in etabs(r)}.get(ref)
    ev['ref'] = {k: refe.get(k) for k in ('siret', 'adresse', 'date_creation', 'date_fermeture', 'etat_administratif')} if refe else None
    siren = ref[:9]
    alive, closed = [], []
    for s, e in seen.items():
        if e.get('etat_administratif') != 'A' or not str(e.get('activite_principale', '')).startswith('56'): continue
        try: d = M.dist(lat, lng, float(e['latitude']), float(e['longitude']))
        except Exception: continue
        sc = max(best_name(name, e['_names']), best_name(refe['_names'][0], e['_names']) if refe and refe['_names'] else 0)
        row = {'siret': s, 'names': e['_names'][:3], 'adresse': e.get('adresse'), 'd_m': round(d), 'created': e.get('date_creation'), 'score': round(sc, 2)}
        if d <= R_ALIVE and (e['_siren'] == siren or sc >= TH): alive.append(row)
        elif refe and refe.get('latitude'):
            da = M.dist(float(refe['latitude']), float(refe['longitude']), float(e['latitude']), float(e['longitude']))
            if da <= R_ADDR and e['_siren'] != siren and sc < TH and refe.get('date_fermeture') and (e.get('date_creation') or '') > refe['date_fermeture']:
                row['d_ref_m'] = round(da); closed.append(row)
    ev['sirene_alive'] = alive; ev['sirene_replaced'] = closed
    # Alim'confiance: контроль за год по SIRET либо рядом с совпавшим именем
    sel = 'app_libelle_etablissement,siret,date_inspection,adresse_activite'
    q = urllib.parse.quote("siret='%s' and date_inspection>=date'%s'" % (ref, YEAR_AGO))
    a = get('https://dgal.opendatasoft.com/api/explore/v2.1/catalog/datasets/export_alimconfiance/records?limit=3&select=%s&where=%s' % (sel, q)); time.sleep(.3)
    al = a.get('results', [])
    q2 = urllib.parse.quote("within_distance(geores,geom'POINT(%s %s)',%dm) and date_inspection>=date'%s'" % (lng, lat, int(R_ALIVE), YEAR_AGO))
    b = get('https://dgal.opendatasoft.com/api/explore/v2.1/catalog/datasets/export_alimconfiance/records?limit=20&select=%s&where=%s' % (sel, q2)); time.sleep(.3)
    near = [x for x in b.get('results', []) if x.get('siret') == ref or best_name(name, [x.get('app_libelle_etablissement')]) >= TH]
    ev['alim_ref'] = al; ev['alim_near_match'] = near; ev['alim_err'] = a.get('_error') or b.get('_error'); ev['sirene_ok'] = bool(seen)
    if alive or al or near: st, why = 'alive', "SIRENE активный того же SIREN/имени <=60 м или Alim'confiance <=12 мес"
    elif closed: st, why = 'closed', 'SIRENE: на том же адресе активное 56.* другого владельца/имени, создано после закрытия ref'
    else: st, why = 'unclear', ''
    return st, why, ev


def load_sla_row(ref):
    fn, line = ref.split(':')[0], int(ref.split(':')[1])
    for i, row in enumerate(csv.DictReader(open(P + 'registry/' + fn, encoding='utf8', newline=''))):
        if i + 2 == line: return row


def nyc(rec):
    lat, lng, name, ref = rec['lat'], rec['lng'], rec['name'], rec['ref']
    sla = load_sla_row(ref)
    names = [name, sla['DBA'], sla['LegalName']]
    m = re.search(r'POINT \((-?[\d.]+) (-?[\d.]+)\)', sla.get('Georeference') or '')
    slat, slng = float(m.group(2)), float(m.group(1))
    ev = {'sla': {k: sla[k] for k in ('DBA', 'LegalName', 'Actual Address Of Premises', 'Zip Code', 'Expiration Date', 'Description')}}

    def box(la, lo):
        w = "latitude between '%.6f' and '%.6f' and longitude between '%.6f' and '%.6f'" % (la - .0008, la + .0008, lo - .0011, lo + .0011)
        p = {'$select': 'camis,dba,building,street,zipcode,latitude,longitude,max(inspection_date) as last', '$where': w,
             '$group': 'camis,dba,building,street,zipcode,latitude,longitude', '$limit': '200'}
        r = get('https://data.cityofnewyork.us/resource/43nn-pn8j.json?' + urllib.parse.urlencode(p, quote_via=urllib.parse.quote)); time.sleep(.3)
        return r
    err = None
    rows = {}
    for r in (box(lat, lng), box(slat, slng)):
        if isinstance(r, dict): err = r.get('_error'); continue
        for x in r:
            if 'camis' in x: rows[x['camis']] = x
    alive, closed = [], []
    for c, x in rows.items():
        try: x_lat, x_lng = float(x['latitude']), float(x['longitude'])
        except Exception: continue
        last = (x.get('last') or '')[:10]
        if last < YEAR_AGO: continue
        sc = max(best_name(n, [x.get('dba')]) for n in names)
        row = {'camis': c, 'dba': x.get('dba'), 'addr': '%s %s %s' % (x.get('building'), x.get('street'), x.get('zipcode')), 'last': last, 'score': round(sc, 2)}
        d = M.dist(lat, lng, x_lat, x_lng); da = M.dist(slat, slng, x_lat, x_lng)
        if d <= R_ALIVE and sc >= TH: row['d_m'] = round(d); alive.append(row)
        elif da <= R_ADDR and sc < TH: row['d_sla_m'] = round(da); closed.append(row)
    ev['dohmh_alive'] = alive; ev['dohmh_replaced'] = closed; ev['dohmh_err'] = err; ev['dohmh_rows_total'] = len(rows)
    if alive: st, why = 'alive', 'DOHMH: инспекция того же имени <=60 м, <=12 мес'
    elif closed: st, why = 'closed', 'DOHMH: на адресе лицензии SLA другое заведение (иной CAMIS/имя), инспекция <=12 мес'
    else: st, why = 'unclear', ''
    return st, why, ev


if __name__ == '__main__':
    d = json.load(open(P + 'tk006/verify_40.json', encoding='utf8'))
    old = {x['venueId']: x for x in json.load(open(P + 'tk006/verify_results.json', encoding='utf8'))}
    out = []
    for i, rec in enumerate(d):
        try:
            st, why, ev = (paris if rec['city'] == 'Paris' else nyc)(rec)
        except Exception as e:
            st, why, ev = 'unclear', 'ошибка: %r' % e, {}
        o = old.get(rec['venueId'], {})
        if o.get('status') == 'closed' and st != 'closed':  # явная страница о закрытии из прошлой сверки остаётся в силе
            st, why = 'closed', 'страница о закрытии (прошлая сверка): ' + o.get('source', '')
        out.append({'i': i, 'city': rec['city'], 'name': rec['name'], 'venueId': rec['venueId'], 'status': st, 'why': why, 'ev': ev})
        print(i, rec['city'], rec['name'], '->', st, flush=True)
        json.dump(out, open(P + 'tk006/verify2_results.json', 'w', encoding='utf8'), ensure_ascii=False, indent=1)

